/* ===================== v44 : français / anglais =====================
   Le jeu est écrit en français. En anglais, un traducteur réécrit le texte AFFICHÉ (nœuds de texte + placeholder,
   title, aria-label) grâce au dictionnaire I18N_EN : phrases exactes, puis modèles avec des nombres ou des noms.
   Avantage : pas besoin de toucher aux ~1000 phrases du code. Le chat (.chat-msg) et les zones data-noi18n ne sont
   jamais traduits. Les boîtes confirmT() passent par T(). Phrase oubliée = elle reste en français (rien ne casse). */
var LANG = (function(){ try{ var s = localStorage.getItem('rikiki_lang'); if(s==='fr' || s==='en') return s; }catch(e){}
  return /^fr/i.test((navigator.language||'fr')) ? 'fr' : 'en'; })();
var i18nMissing = null; // tests : ensemble des textes restés en français
var i18nDone = {};     // textes anglais déjà produits (pour ne pas les retraiter)
function i18nExact(){ return (typeof I18N_EN!=='undefined' && I18N_EN.exact) || {}; }
function i18nPatterns(){ return (typeof I18N_EN!=='undefined' && I18N_EN.patterns) || []; }
function T(fr){
  if(LANG!=='en' || fr==null) return fr;
  var s = String(fr), m = s.match(/^(\s*)([\s\S]*?)(\s*)$/), core = m[2];
  if(!core) return s;
  var ex = i18nExact();
  if(Object.prototype.hasOwnProperty.call(ex, core)){ i18nDone[ex[core]] = 1; return m[1]+ex[core]+m[3]; }
  if(i18nDone[core]) return s; // déjà traduit
  var ps = i18nPatterns();
  for(var i=0;i<ps.length;i++){
    if(ps[i][0].test(core)){
      var rep = ps[i][1];
      var out = core.replace(ps[i][0], function(){ var a = arguments;
        if(typeof rep==='function') return rep.apply(null, a);
        return rep.replace(/\$(\d)/g, function(_, k){ return a[+k]==null ? '' : T(a[+k]); }); });
      i18nDone[out] = 1;
      return m[1]+out+m[3];
    }
  }
  if(i18nMissing && /[a-zA-ZÀ-ÿ]{2,}/.test(core)) i18nMissing[core] = (i18nMissing[core]||0)+1;
  return s;
}
function i18nSkip(el){ return !!(el && el.closest && el.closest('.chat-msg, [data-noi18n], script, style, textarea')); }
function i18nNode(n){
  if(LANG!=='en' || !n) return;
  if(n.nodeType===3){
    if(!n.nodeValue || !/[A-Za-zÀ-ÿ]/.test(n.nodeValue) || i18nSkip(n.parentElement)) return;
    var t = T(n.nodeValue); if(t!==n.nodeValue) n.nodeValue = t; return;
  }
  if(n.nodeType!==1 || i18nSkip(n)) return;
  ['placeholder','title','aria-label'].forEach(function(a){ var v = n.getAttribute(a); if(v && /[A-Za-zÀ-ÿ]/.test(v)){ var t = T(v); if(t!==v) n.setAttribute(a, t); } });
  if(n.tagName==='INPUT' && (n.type==='button' || n.type==='submit') && n.value){ var tv = T(n.value); if(tv!==n.value) n.value = tv; }
  for(var c=n.firstChild; c; c=c.nextSibling) i18nNode(c);
}
var i18nObserver = null;
function i18nStart(){
  try{ document.documentElement.setAttribute('lang', LANG); }catch(e){}
  if(LANG!=='en' || i18nObserver || !window.MutationObserver) return;
  i18nNode(document.body);
  i18nObserver = new MutationObserver(function(list){
    list.forEach(function(r){
      if(r.type==='characterData') i18nNode(r.target);
      else if(r.type==='attributes') i18nNode(r.target);
      else r.addedNodes.forEach(function(x){ i18nNode(x); });
    });
  });
  i18nObserver.observe(document.body, { childList:true, subtree:true, characterData:true, attributes:true, attributeFilter:['placeholder','title','aria-label'] });
}
function confirmT(msg){ return window.confirm(T(msg)); }
function setLang(l){ try{ localStorage.setItem('rikiki_lang', l); }catch(e){} location.reload(); }
document.addEventListener('click', function(e){
  var el = e.target.closest ? e.target.closest('[data-action="set-lang"]') : null; if(!el) return;
  setLang(el.getAttribute('data-lang')==='en' ? 'en' : 'fr');
});
