// Petits portraits dessinés (couleur de la carte) : couronne et barbe pour le Roi, diadème et cheveux longs pour la Dame, chapeau à plume pour le Valet
function faceSvg(rank, sym){
  var robe = '<path d="M5 60 Q6 41 20 39 Q34 41 35 60 Z" fill="currentColor"/>'
    + '<text x="20" y="55" text-anchor="middle" font-size="11" fill="#FBF6EA" font-family="Georgia,serif">'+sym+'</text>';
  var head = '<circle cx="20" cy="27" r="7" fill="#FBF6EA" stroke="currentColor" stroke-width="1.6"/>'
    + '<circle cx="17.6" cy="26.2" r="0.9" fill="currentColor"/><circle cx="22.4" cy="26.2" r="0.9" fill="currentColor"/>';
  var top = '';
  if(rank==='K'){
    top = '<path d="M14 30 Q20 38.5 26 30 Q23 33 20 33 Q17 33 14 30 Z" fill="currentColor"/>'
      + '<path d="M11.5 20 L11.5 10.5 L15.8 14.8 L20 7 L24.2 14.8 L28.5 10.5 L28.5 20 Z" fill="currentColor"/>'
      + '<circle cx="20" cy="16.5" r="1.3" fill="#FBF6EA"/>';
  } else if(rank==='Q'){
    top = '<path d="M11.5 29 Q10.5 17 20 17 Q29.5 17 28.5 29 L29.5 38 Q25 35.5 25.5 29 Z M14.5 29 Q15 35.5 10.5 38 Z" fill="currentColor"/>'
      + '<path d="M13.5 20.5 Q20 13 26.5 20.5 L24.5 17.6 L22.2 19.2 L20 15.2 L17.8 19.2 L15.5 17.6 Z" fill="currentColor"/>'
      + '<circle cx="20" cy="14.6" r="1.4" fill="currentColor"/>';
  } else {
    top = '<path d="M11.8 22 Q12.5 12.5 21 13 Q28.5 13.5 28.2 22 Z" fill="currentColor"/>'
      + '<path d="M26 14.5 Q31 5 37 5.5 Q33.5 8 28.5 16 Z" fill="currentColor" opacity="0.75"/>'
      + '<path d="M14 36.5 L20 40.5 L26 36.5" fill="none" stroke="currentColor" stroke-width="1.6"/>';
  }
  return '<svg class="fig" viewBox="0 0 40 60" aria-hidden="true">'+robe+(rank==='Q' ? top+head : head+top)+'</svg>';
}
// Figures illustrées (image fournie par les joueurs) + symboles disposés comme sur un vrai jeu
var FACE_IMG = {"SJ": "data:image/png;base64,", "SQ": "data:image/png;base64,", "SK": "data:image/png;base64,", "HJ": "data:image/png;base64,", "HQ": "data:image/png;base64,", "HK": "data:image/png;base64,", "DJ": "data:image/png;base64,", "DQ": "data:image/png;base64,", "DK": "data:image/png;base64,", "CJ": "data:image/png;base64,", "CQ": "data:image/png;base64,", "CK": "data:image/png;base64,"};
// positions des symboles (x %, y %, retourné) pour 2 à 10
var PIP_LAYOUT = (function(){
  var L=33, C=50, R=67, T=20, B=80;
  function m(list){ return list.map(function(p){ return { x:p[0], y:p[1], r:p[1]>50 || (p[1]===50 && p[2]) }; }); }
  return {
    '2': m([[C,T],[C,B]]),
    '3': m([[C,T],[C,50],[C,B]]),
    '4': m([[L,T],[R,T],[L,B],[R,B]]),
    '5': m([[L,T],[R,T],[C,50],[L,B],[R,B]]),
    '6': m([[L,T],[R,T],[L,50],[R,50],[L,B],[R,B]]),
    '7': m([[L,T],[R,T],[C,35],[L,50],[R,50],[L,B],[R,B]]),
    '8': m([[L,T],[R,T],[C,35],[L,50],[R,50],[C,65],[L,B],[R,B]]),
    '9': m([[L,T],[R,T],[L,40],[R,40],[C,50],[L,60],[R,60],[L,B],[R,B]]),
    '10': m([[L,T],[R,T],[C,30],[L,40],[R,40],[L,60],[R,60],[C,70],[L,B],[R,B]])
  };
})();
function pipsHtml(rank, sym){
  var lay = PIP_LAYOUT[rank]; if(!lay) return '';
  return '<div class="pips">'+lay.map(function(p){ return '<span class="'+(p.r?'r':'')+'" style="left:'+p.x+'%; top:'+p.y+'%;">'+sym+'</span>'; }).join('')+'</div>';
}
